70	/**
71	 * Detects the best authentication type based on environment variables.
72	 *
73	 * Checks in order:
74	 * 1. GOOGLE_GENAI_USE_GCA=true -> LOGIN_WITH_GOOGLE
75	 * 2. GOOGLE_GENAI_USE_VERTEXAI=true -> USE_VERTEX_AI
76	 * 3. GEMINI_API_KEY -> USE_GEMINI
77	 */
78	export function getAuthTypeFromEnv(): AuthType | undefined {
79	  if (process.env['GOOGLE_GENAI_USE_GCA'] === 'true') {
80	    return AuthType.LOGIN_WITH_GOOGLE;
81	  }
82	  if (process.env['GOOGLE_GENAI_USE_VERTEXAI'] === 'true') {
83	    return AuthType.USE_VERTEX_AI;
84	  }
85	  if (process.env['GOOGLE_GEMINI_BASE_URL']) {
86	    return AuthType.GATEWAY;
87	  }
88	  if (process.env['GEMINI_API_KEY']) {
89	    return AuthType.USE_GEMINI;
90	  }
91	  if (
92	    process.env['CLOUD_SHELL'] === 'true' ||
93	    process.env['GEMINI_CLI_USE_COMPUTE_ADC'] === 'true'
94	  ) {
95	    return AuthType.COMPUTE_ADC;
96	  }
97	  return undefined;
98	}
