14	export async function createCodeAssistContentGenerator(
15	  httpOptions: HttpOptions,
16	  authType: AuthType,
17	  config: Config,
18	  sessionId?: string,
19	): Promise<ContentGenerator> {
20	  if (
21	    authType === AuthType.LOGIN_WITH_GOOGLE ||
