58	/**
59	 * Rough token estimate for non-Part config objects (tool definitions, etc.)
60	 * where estimateTokenCountSync cannot be used directly.
61	 */
62	function estimateConfigTokens(value: unknown): number {
63	  return Math.floor(JSON.stringify(value).length / 4);
64	}
65	
66	/**
67	 * Estimates the context breakdown for telemetry. All returned fields are
68	 * additive (non-overlapping), so their sum approximates the total context size.
69	 *
70	 * - system_instructions: tokens from system instruction config
71	 * - tool_definitions: tokens from non-MCP tool definitions
72	 * - history: tokens from conversation history, excluding tool call/response parts
73	 * - tool_calls: per-tool token counts for non-MCP function call + response parts
74	 * - mcp_servers: tokens from MCP tool definitions + MCP tool call/response parts
75	 *
76	 * MCP tool calls are excluded from tool_calls and counted only in mcp_servers
77	 * to keep fields non-overlapping and avoid leaking MCP server names in telemetry.
78	 */
79	export function estimateContextBreakdown(
80	  contents: Content[],
81	  config?: GenerateContentConfig,
82	): ContextBreakdown {
83	  let systemInstructions = 0;
84	  let toolDefinitions = 0;
85	  let history = 0;
86	  let mcpServers = 0;
87	  const toolCalls: Record<string, number> = {};
88	
89	  if (config?.systemInstruction) {
90	    systemInstructions += estimateConfigTokens(config.systemInstruction);
91	  }
92	
93	  if (config?.tools) {
94	    for (const tool of config.tools) {
95	      const toolTokens = estimateConfigTokens(tool);
96	      if (
97	        tool &&
98	        typeof tool === 'object' &&
99	        'functionDeclarations' in tool &&
100	        tool.functionDeclarations
101	      ) {
102	        let mcpTokensInTool = 0;
103	        for (const func of tool.functionDeclarations) {
104	          if (func.name && isMcpToolName(func.name)) {
105	            mcpTokensInTool += estimateConfigTokens(func);
106	          }
107	        }
108	        mcpServers += mcpTokensInTool;
109	        toolDefinitions += toolTokens - mcpTokensInTool;
110	      } else {
111	        toolDefinitions += toolTokens;
112	      }
113	    }
114	  }
115	
116	  for (const content of contents) {
117	    for (const part of content.parts || []) {
118	      if (part.functionCall) {
119	        const name = part.functionCall.name || 'unknown';
120	        const tokens = estimateTokenCountSync([part]);
121	        if (isMcpToolName(name)) {
122	          mcpServers += tokens;
123	        } else {
124	          toolCalls[name] = (toolCalls[name] || 0) + tokens;
125	        }
126	      } else if (part.functionResponse) {
127	        const name = part.functionResponse.name || 'unknown';
128	        const tokens = estimateTokenCountSync([part]);
129	        if (isMcpToolName(name)) {
130	          mcpServers += tokens;
131	        } else {
132	          toolCalls[name] = (toolCalls[name] || 0) + tokens;
133	        }
134	      } else {
135	        history += estimateTokenCountSync([part]);
136	      }
137	    }
138	  }
139	
140	  return {
141	    system_instructions: systemInstructions,
142	    tool_definitions: toolDefinitions,
143	    history,
144	    tool_calls: toolCalls,
145	    mcp_servers: mcpServers,
146	  };
147	}
