/**
 * Platform-specific installation information for the Antigravity CLI.
 */
export interface AntigravityInstallInfo {
  /** Human-readable name of the detected platform. */
  platformName: string;
  /** The shell command used to install the Antigravity CLI on that platform. */
  installCmd: string;
}

/**
 * Returns platform-specific installation information for the Antigravity CLI.
 *
 * Detection is based on the current operating system (and, on Windows, whether
 * the invocation is coming from PowerShell as indicated by the `PSModulePath`
 * environment variable).
 *
 * @param platform The platform to detect for. Defaults to `process.platform`.
 * @param env The environment to inspect. Defaults to `process.env`.
 * @returns Installation info for the platform, or `null` when unsupported.
 */
export function getAntigravityInstallInfo(
  platform: NodeJS.Platform = process.platform,
  env: NodeJS.ProcessEnv = process.env,
): AntigravityInstallInfo | null {
  switch (platform) {
    case 'darwin':
      return {
        platformName: 'macOS',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.sh | bash',
      };
    case 'linux':
      return {
        platformName: 'Linux',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.sh | bash',
      };
    case 'win32':
      if (env['PSModulePath']) {
        return {
          platformName: 'Windows (PowerShell)',
          installCmd: 'irm https://antigravity.google/cli/install.ps1 | iex',
        };
      }
      return {
        platformName: 'Windows (Command Prompt)',
        installCmd:
          'curl -fsSL https://antigravity.google/cli/install.cmd -o install.cmd && install.cmd && del install.cmd',
      };
    default:
      return null;
  }
}
